{
  "extractions": [
    {
      "unit": "F002",
      "unit_attributes": {
        "statement": "For application review, a review notice (RN) means a written request for missing application records.",
        "kind": "definition",
        "modality": "not_stated",
        "scope_text": "For application review",
        "scope_quotes": [
          "F002"
        ]
      }
    },
    {
      "unit": "F003",
      "unit_attributes": {
        "statement": "In the context of application review, applicants must return the review notice (RN) within ten days unless a reviewer extends the deadline.",
        "kind": "requirement",
        "modality": "must",
        "scope_text": "For application review",
        "scope_quotes": [
          "F001",
          "F002"
        ],
        "modality_quote": "must"
      }
    },
    {
      "unit": "F004",
      "unit_attributes": {
        "statement": "In the context of application review, reviewers may extend the deadline to return the review notice (RN) by five days only with a supervisor's approval.",
        "kind": "permission",
        "modality": "may",
        "scope_text": "For application review",
        "scope_quotes": [
          "F001",
          "F002"
        ],
        "modality_quote": "may"
      }
    },
    {
      "unit": "F006",
      "unit_attributes": {
        "statement": "Within equipment inspections, a review notice (RN) means a record that an inspection was completed; it is not a request for records.",
        "kind": "definition",
        "modality": "not_stated",
        "scope_text": "Within equipment inspections",
        "scope_quotes": [
          "F006"
        ]
      }
    },
    {
      "unit": "F007",
      "unit_attributes": {
        "statement": "Within equipment inspections, inspectors must issue a review notice (RN) after completing an inspection.",
        "kind": "requirement",
        "modality": "must",
        "scope_text": "Within equipment inspections",
        "scope_quotes": [
          "F005",
          "F006"
        ],
        "modality_quote": "must"
      }
    },
    {
      "unit": "F008",
      "unit_attributes": {
        "statement": "Within equipment inspections, operators may archive that review notice (RN) only after a manager's approval.",
        "kind": "permission",
        "modality": "may",
        "scope_text": "Within equipment inspections",
        "scope_quotes": [
          "F005",
          "F006"
        ],
        "modality_quote": "may"
      }
    },
    {
      "unit": "F009",
      "unit_attributes": {
        "statement": "Within equipment inspections, where an RN is archived with manager approval, you must retain a copy of the approval email.",
        "kind": "requirement",
        "modality": "must",
        "scope_text": "Within equipment inspections, regarding manager approval for archiving an RN",
        "scope_quotes": [
          "F005",
          "F008"
        ],
        "modality_quote": "must"
      }
    },
    {
      "unit": "F011",
      "unit_attributes": {
        "statement": "Under general record handling, records must be retained for two years.",
        "kind": "requirement",
        "modality": "must",
        "scope_text": "General record handling",
        "scope_quotes": [
          "F010"
        ],
        "modality_quote": "must"
      }
    },
    {
      "unit": "F012",
      "unit_attributes": {
        "statement": "ZX is an external reference code whose meaning is not supplied here.",
        "kind": "statement",
        "modality": "not_stated",
        "references": [
          "ZX"
        ]
      }
    }
  ]
}
